    @Test("realPart")
    func test_realPart() throws {
        // Swift exposes realPart() as a method, not a free function
        try withIntegrationState(seed: 28164) {
            let r = MLXRandom.normal([4, 3], dtype: .float32, loc: 0.0, scale: 1.0)
            let i = MLXRandom.normal([4, 3], dtype: .float32, loc: 0.0, scale: 1.0)
            let c = r + i.asImaginary()
            let result = c.realPart()
            expectSummary(
                result,
                ArraySummary(
                    shape: [4, 3],
                    dtype: .float32,
                    mean: -0.27432000637054443,
                    minimum: -2.3572521209716797,
                    maximum: 0.864957869052887,
                    absoluteSum: 8.50927734375,
                    positionChecksum: 3.2805039087931314,
                    sampleIndices: [0, 2, 4, 7, 9, 11],
                    samples: [
                        -2.3572521209716797, -0.278932124376297, 0.36380791664123535,
                        0.6124622225761414, 0.09972750395536423, -0.07274171710014343,
                    ]),
                tolerance: .float32)
        }
    }

